function(...)
  local keys = {...}
  if #keys < 1 then error("Hotkey 至少需要一个按键。", 2) end
  local held = {}
  local ok, err = pcall(function()
    for i = 1, #keys do KeyDown(keys[i]); held[#held + 1] = keys[i] end
  end)
  for i = #held, 1, -1 do
    local released, releaseError = pcall(function() KeyUp(held[i]) end)
    if not released and ok then ok, err = false, releaseError end
  end
  if not ok then error(err, 0) end
end

